export const PRIVACY_HTML = {
 "ko": "<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>SystemBoost 개인정보 처리방침</title>\n<style nonce=\"__NONCE__\">\n:root{--bg:#0b0b0c;--card:#141416;--line:#2a2a2e;--text:#e8e6e3;--muted:#8b8a88;--accent:#ff7a1a;--warn:#f5c04a}\n*{box-sizing:border-box}\nbody{background:var(--bg);color:var(--text);font-family:system-ui,-apple-system,\"Segoe UI\",\"Malgun Gothic\",sans-serif;max-width:900px;margin:0 auto;padding:24px 16px 64px;line-height:1.65;overflow-wrap:anywhere}\nheader{display:flex;align-items:baseline;justify-content:space-between;gap:12px;flex-wrap:wrap;font-size:14px}\nheader .brand{color:var(--accent);font-weight:700}header nav{display:flex;gap:16px;flex-wrap:wrap}\na{color:var(--accent)}\nh1{color:var(--accent);font-size:26px;margin:20px 0 12px}h2{font-size:19px;margin:32px 0 10px;padding-top:12px;border-top:1px solid var(--line)}h3{font-size:16px;margin:20px 0 8px}\np,li{margin:6px 0}ul{padding-left:22px}\n.toc{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:12px 16px;margin:18px 0;font-size:14px}.toc ol{margin:6px 0 0;padding-left:22px}\n.tbl{overflow-x:auto;margin:10px 0}\ntable{border-collapse:collapse;width:100%;font-size:14px}\nth,td{border:1px solid var(--line);padding:8px 10px;text-align:left;vertical-align:top}\nth{background:var(--card);color:var(--muted);font-weight:600}td{min-width:7em}\n.blank{color:var(--warn);font-weight:600}\n</style>\n</head>\n<body>\n<header><span class=\"brand\">SystemBoost</span><nav><a href=\"/help\">고객센터</a><a href=\"/privacy?lang=en\" hreflang=\"en\">English summary</a></nav></header>\n<main>\n<h1>SystemBoost 개인정보 처리방침</h1>\n<p>SystemBoost 판매자(이하 &quot;판매자&quot;)는 SystemBoost 앱, 라이선스 서버, 고객센터(앱의 &#39;고객센터&#39;와 웹 /help)를 운영하면서 아래와 같이 개인정보를 처리해요. 판매자 정보는 앱의 ★ 플랜 화면, 고객센터의 &#39;판매자 정보&#39;, 웹 /help에서 볼 수 있어요.</p>\n<p>시행일: {{EFFECTIVE_DATE}}</p>\n<nav class=\"toc\" aria-label=\"목차\"><b>목차</b><ol><li><a href=\"#s1\">한눈에 보기</a></li><li><a href=\"#s2\">제1조 처리하는 개인정보와 목적</a></li><li><a href=\"#s3\">제2조 보유 기간, 파기 절차와 방법</a></li><li><a href=\"#s4\">제3조 제3자 제공</a></li><li><a href=\"#s5\">제4조 처리 위탁과 국외 이전</a></li><li><a href=\"#s6\">제5조 정보주체의 권리와 행사 방법</a></li><li><a href=\"#s7\">제6조 자동 수집 장치</a></li><li><a href=\"#s8\">제7조 이 PC에만 남는 정보</a></li><li><a href=\"#s9\">제8조 만 14세 미만 아동</a></li><li><a href=\"#s10\">제9조 안전성 확보 조치</a></li><li><a href=\"#s11\">제10조 개인정보 보호책임자</a></li><li><a href=\"#s12\">제11조 권익침해 구제 방법</a></li><li><a href=\"#s13\">제12조 처리방침의 변경</a></li></ol></nav>\n<h2 id=\"s1\">한눈에 보기</h2>\n<ul><li>앱은 회원 가입 없이 쓸 수 있어요. 회원 가입에는 메일 주소나 이름을 받지 않아요.</li><li>카드 번호는 Lemon Squeezy 결제창에서만 입력해요. 카드 번호는 SystemBoost 앱과 판매자 서버에 오지 않고, 판매자 서버는 카드에 관한 정보를 저장하지 않아요.</li><li>판매자 서버는 Cloudflare(미국 회사)에서 돌아가고, 회원 정보는 Supabase에 있어요. 그래서 개인정보가 국외에서 처리되고 보관돼요(제4조).</li><li>키 기록과 메일 주소 색인처럼 보관 기간을 정하지 않은 기록이 있어요. 무엇이 얼마나 남는지는 제2조에 하나씩 적었어요.</li><li>개인정보를 광고나 마케팅에 쓰지 않고, 다른 사람에게 팔거나 제공하지 않아요.</li></ul>\n<h2 id=\"s2\">제1조 처리하는 개인정보와 목적</h2>\n<div class=\"tbl\"><table><thead><tr><th>언제</th><th>처리하는 항목</th><th>목적</th></tr></thead><tbody><tr><td>키를 등록한 앱을 켤 때와, 켜 둔 동안 20시간에 한 번까지 (인터넷 연결 시)</td><td>라이선스 키 식별 번호(키에서 계산한 16자리)</td><td>키가 막혔는지 확인. 판매자 서버는 이 요청을 저장소에 남기지 않아요</td></tr><tr><td>구독 키가 끝나기 7일 전</td><td>구독 번호, 지금 쓰는 키 전체(그 구독의 키인지 확인에만 쓰고 저장하지 않아요)</td><td>다음 기간의 키 받기. 판매자 서버는 이 요청을 저장소에 남기지 않아요</td></tr><tr><td>계좌이체 · 직접 결제</td><td>주문 코드, 플랜, 결제 방식, 주문 상태와 시각, 사용자가 적은 입금자명과 결제 메모, 할인 티켓을 쓴 경우 그 할인율. 판매자가 승인하면 키 식별 번호, 판매자가 적은 메일 주소(선택), 묶음 키의 개수. 판매자가 거절하면 거절 사유, 환불하면 환불 시각</td><td>결제 확인과 키 발급. 판매자는 결제 서비스나 계좌의 결제 내역(입금자명, 금액, 메모)을 주문과 맞춰 봐요</td></tr><tr><td>카드 결제</td><td>Lemon Squeezy가 판매자 서버로 보내는 결제 알림의 결제 메일 주소, 구독 번호, 주문 번호, 결제 번호(자동 결제 한 번마다의 번호), 산 상품(플랜), 다음 결제일, 구독 상태, 시험 결제인지, 주문 코드. 판매자 서버는 이 가운데 메일 주소, 구독 번호, 주문 번호, 결제 번호, 플랜, 만료일(다음 결제일로 계산), 시험 결제인지, 주문 코드만 저장하고, 결제 알림에 들어 있는 다른 정보(이름 등)는 저장하지 않아요. 메일 주소는 주문, 키 기록, 메일 주소로 키를 찾는 색인, 판매자 작업 기록에 남아요</td><td>키 자동 발급과 갱신, 환불한 키 막기, 키를 잃어버렸을 때 찾아 주기</td></tr><tr><td>키를 발급할 때 (모든 키)</td><td>키 전체, 키 식별 번호, 플랜, 발급일과 만료일, 받은 경로(직접 결제, 카드, 추천 코드와 초대, 판매자 발급), 메일 주소(카드 결제 메일 또는 판매자가 적은 메일), 메모(주문 코드, 판매자가 적은 메모, 판매자가 메모를 비우고 승인한 직접 결제는 입금자명과 결제 메모, 추천 코드, 초대 보상이면 회원 아이디), 구독 번호, 시험 결제의 키인지, 막았는지와 그 사유. 키 안에도 플랜, 메일 주소, 발급일, 구독 번호, 만료일이 들어 있어서, 키를 다른 사람에게 보여 주면 메일 주소도 함께 보여요</td><td>키 발급, 확인, 막기, 다시 보내기, 환불</td></tr><tr><td>추천 코드나 초대 코드를 쓸 때</td><td>코드, 앱이 만든 무작위 기기 번호</td><td>한 기기가 코드를 한 번만 쓰게 하기. 회원 가입 때도 기기 번호를 보내지만, 초대 코드를 쓴 경우에만 저장해요</td></tr><tr><td>판매자가 추천 코드를 만들 때</td><td>코드, 판매자가 적은 이름표(예: 코드를 준 사람), 플랜과 기간, 사용 횟수</td><td>추천 코드 관리와 코드를 퍼뜨린 사람의 보상</td></tr><tr><td>회원 가입과 회원 기능 (선택)</td><td>아이디, 비밀번호와 복구 코드(해시값으로만 저장), 가입과 마지막 로그인 시각, 동의한 안내문의 판과 동의 시각, 초대 코드, 초대한 회원, 초대 수와 보상 일수, 할인 티켓(할인율, 만료일, 쓴 주문 코드, 쓴 시각), 로그인 실패 횟수와 잠금 시각, 차단 여부, 로그인 세션(해시값과 만료 시각)</td><td>회원 관리, 초대 보상, 할인 티켓</td></tr><tr><td>고객센터 문의와 환불 요청</td><td>필수: 문의 종류, 제목, 내용, 판매자의 답, 글마다의 시각, 문의 상태, 동의한 시각, 언어, 확인 코드(해시값), 앱에서 회원으로 로그인 중이면 회원 아이디, 환불 요청이면 환불 사유. 적거나 고른 경우만: 연락처, 주문 코드, 키 식별 번호(키 전체를 보냈다면 서명을 확인했다는 표시도), 앱 정보(앱 버전, 운영체제, GPU 이름). 환불 요청에는 서버가 가진 주문과 키 정보를 붙여요: 플랜, 키를 받은 날과 만료일, 받은 경로, 구독 번호, 주문 코드, 입금자명, 주문 상태, 결제 방식, 키를 받은 지 며칠, 적은 키가 다른 구매의 키이면 그 키 식별 번호와 주문 코드. 판매자는 승인이나 거절(거절 사유), 환불 금액, 막은 키를 적어요</td><td>문의에 답하기, 청약철회와 환불 처리, 그 기록</td></tr><tr><td>구독 관리 (카드 구독 키)</td><td>키 전체(서명 확인에만 쓰고 저장하지 않아요), 구독 번호</td><td>Lemon Squeezy에서 그 구독의 관리 페이지 주소를 받아 열어 주기</td></tr><tr><td>사용 통계 (선택: 사용권 계약 동의 화면의 &#39;사용 통계 보내기&#39;로 골라요. 처음에는 체크되어 있고, 나중에 설정에서 바꿀 수 있어요)</td><td>앱이 만든 무작위 설치 번호, 앱 버전, 운영체제, 플랜, 프레임 생성 배수, 원클릭 게임 부스트 사용 여부, 접속한 국가(Cloudflare가 알려 줘요), 처음과 마지막 연결 시각</td><td>사용 현황 파악, 서버 부하에 맞춰 보내는 간격 조절</td></tr><tr><td>너무 많은 요청을 막을 때</td><td>IP 주소로 만든 해시값(회원 가입과 로그인, 고객센터 요청), 고객센터의 하루 한도를 셀 때 키 식별 번호나 주문 코드별 요청 수, 판매자 화면에 접속한 IP 주소로 만든 해시값(비밀번호를 틀린 횟수를 셀 때), 구독 관리 링크를 받은 키 식별 번호별 하루 횟수</td><td>남용과 비밀번호 추측 막기</td></tr><tr><td>판매자 작업과 자동 처리를 기록할 때</td><td>판매자의 작업(키 발급과 막기, 결제 승인과 거절, 주문 삭제, 환불 승인 · 거절 · 완료, 회원 차단과 삭제, 복구 코드 재발급, 추천 코드 관리, 문의 삭제 등)과 자동 처리(카드 결제 승인과 갱신, 추천 코드 사용, 초대 보상)의 시각과 상세: 주문 코드, 키 식별 번호, 구독 번호, 회원 아이디, 추천 코드, 문의 번호, 환불 금액, 거절 사유 등. 메일 주소는 가린 형태(예: a***@e***.com)로, 키 메모 · 입금자명 · 결제 메모 · 이름표는 첫 글자만 남겨요. 구독 관리 링크를 내줄 때마다 키 식별 번호와 구독 번호를 남겨요</td><td>판매자가 무엇을 했는지 확인</td></tr><tr><td>판매자가 Cloudflare의 로그 기능을 켠 경우</td><td>판매자 서버로 온 요청의 주소(주문 코드, 키 식별 번호, 구독 번호, 문의 번호, 판매자 화면의 검색어가 들어갈 수 있어요) 같은 요청 정보와 판매자 서버의 오류 기록(회원 데이터베이스 연결 오류의 동작 이름, 상태, 오류 코드와 메시지)</td><td>서버 문제 진단</td></tr></tbody></table></div>\n<ul><li>키 전체를 고객센터에 보내면(환불 요청, 구독 관리) 서버는 서명을 확인하는 데만 쓰고 저장하지 않아요. 문의에는 키 식별 번호만 남아요.</li><li>문의의 확인 코드는 서버에 해시값만 저장해요. 코드를 잃으면 그 문의를 다시 열 수 없어요.</li><li>사용 통계에는 키, 메일 주소, 게임 이름, 하드웨어 정보를 보내지 않고, IP 주소를 저장하지 않아요.</li></ul>\n<h2 id=\"s3\">제2조 보유 기간, 파기 절차와 방법</h2>\n<div class=\"tbl\"><table><thead><tr><th>정보</th><th>보유 기간</th></tr></thead><tbody><tr><td>주문</td><td>주문이 마지막으로 바뀐 날부터 90일</td></tr><tr><td>앱이 키를 받아 가기 위한 대기 정보(키 전체)</td><td>카드 결제 7일, 직접 결제 30일. 고객센터의 환불 요청으로 환불을 마치면 그때 지워요</td></tr><tr><td>키 기록(키 전체, 메일 주소, 메모), 메일 주소로 키를 찾는 색인, Lemon Squeezy 주문 번호와 키의 연결, 막은 키 목록</td><td>보관 기간을 정하지 않았어요 — 판매자가 지울 때까지. 키를 확인하고 막는 데 써요. 막은 키 목록의 한 줄은 판매자가 막기를 풀면 지워요. 판매자 화면에는 나머지를 지우는 기능이 없어서, 지워 달라고 하면 판매자가 Cloudflare 저장소에서 직접 지워요</td></tr><tr><td>구독의 지금 키(구독 번호와 그 구독의 최신 키 전체, 다음 기간의 키를 받아 갈 때 써요)</td><td>구독이 활성 상태가 아니게 되면(해지, 일시정지, 결제 밀림, 만료 등) 또는 그 키를 막으면(환불 등) 지워요</td></tr><tr><td>구독의 키 목록(구독 번호와 그 구독으로 발급한 키의 식별 번호, 최근 200개. 환불할 때 그 구독의 키를 모두 막는 데 써요)</td><td>마지막으로 키를 더한 날부터 400일</td></tr><tr><td>같은 결제 알림을 두 번 처리하지 않기 위한 표시(구독 번호, 결제 번호)</td><td>400일</td></tr><tr><td>구독의 플랜 정보(구독 번호와 플랜)</td><td>보관 기간을 정하지 않았어요 — 판매자가 지울 때까지</td></tr><tr><td>추천 코드와 초대 코드의 기기 번호</td><td>90일</td></tr><tr><td>추천 코드(이름표 포함)</td><td>보관 기간을 정하지 않았어요 — 판매자가 지울 때까지. 판매자 화면에서 지울 수 있어요</td></tr><tr><td>회원 정보</td><td>탈퇴하거나 판매자가 회원을 지울 때까지. 오래 쓰지 않아도 자동으로 지우지 않아요. 탈퇴하면 운영 중인 데이터베이스에서 바로 지우고, Supabase의 백업에는 최대 7일 남았다가 지워져요(아래 백업). 다만 회원 아이디는 키 기록의 메모(초대 보상, 보관 기간을 정하지 않았어요 — 판매자가 지울 때까지), 판매자 작업 기록(180일), 문의(그 문의의 보유 기간)에 남아요</td></tr><tr><td>로그인 세션</td><td>90일. 로그아웃하거나 비밀번호를 바꾸거나 판매자가 회원을 차단하면 바로 지우고, 회원마다 최근 5개만 남겨요. 만료된 세션은 매시간 지워요</td></tr><tr><td>회원 가입과 로그인의 IP 해시값</td><td>정시부터 1시간 단위로 세고, 그 시간이 끝난 뒤 매시 7분에 도는 정리에서 지워요. 보통 1시간 남짓이고, 정리가 실패하면 더 남을 수 있어요</td></tr><tr><td>고객센터 문의</td><td>결제와 환불 문의는 3년, 그 밖의 문의는 1년. 문의가 마지막으로 바뀐 날(글, 답장, 상태 변경, 새 답장 읽음)부터 세요</td></tr><tr><td>환불 요청과 키의 연결(카드 환불 알림이 그 요청을 닫게 하는 것)</td><td>요청을 보낸 날부터 3년</td></tr><tr><td>고객센터의 하루 한도 기록(키 식별 번호나 주문 코드별 요청 수)</td><td>2일</td></tr><tr><td>고객센터 요청의 IP 해시값</td><td>마지막 요청 뒤 1시간까지 (판매자 서버의 저장소, 서버 메모리와 Cloudflare 캐시)</td></tr><tr><td>구독 관리 링크를 받은 키 식별 번호별 하루 횟수</td><td>2일</td></tr><tr><td>구독 관리 페이지 주소</td><td>30분 (서버 메모리와 Cloudflare 캐시)</td></tr><tr><td>새 답장을 읽었다는 표시(문의 번호와 시각)</td><td>1일 (서버 메모리와 Cloudflare 캐시, 고객센터의 하루 한도가 찬 날에만)</td></tr><tr><td>판매자 화면의 &#39;새 소식&#39;(문의 번호, 종류, 시각만)</td><td>30일, 최근 1,000줄까지. 문의를 지우면 함께 지워요</td></tr><tr><td>사용 통계의 설치별 기록</td><td>마지막 연결 뒤 90일. 날짜별 합계(사용자 수 등 숫자만)는 지우지 않아요</td></tr><tr><td>판매자 화면에 접속한 IP 주소의 해시값(비밀번호를 틀린 횟수, 로그인이 이어지는지)</td><td>마지막으로 틀린 뒤 15분, 로그인은 마지막 접속 뒤 30분</td></tr><tr><td>판매자 화면 접속 기록(로그인, 회원 · 구매 정보를 본 시각, 접속한 IP 주소의 해시값, 본 화면과 대상. 검색어는 남기지 않아요)</td><td>1년</td></tr><tr><td>판매자 작업 기록</td><td>180일</td></tr><tr><td>탈퇴하거나 판매자가 지운 회원 아이디의 해시값(서버만 아는 값을 섞어 만들어요. 다른 사람이 같은 아이디로 다시 가입하지 못하게 해요)</td><td>보관 기간을 정하지 않았어요 — 판매자가 지울 때까지</td></tr><tr><td>Cloudflare의 로그(판매자가 켠 경우만)</td><td>Cloudflare가 정한 기간 (Cloudflare 안내: 무료 요금제 3일, 유료 요금제 7일)</td></tr><tr><td>/help가 브라우저에 저장한 문의 목록</td><td>직접 지울 때까지 (제6조)</td></tr></tbody></table></div>\n<ul><li>개인정보는 전자 파일로만 저장해요. 보유 기간이 지나면 저장소가 그 기록을 자동으로 지워요(Cloudflare 저장소의 만료 삭제, 사용 통계와 회원 데이터베이스의 매시간 정리). 서버 메모리에 있는 사본은 기간이 지난 뒤 다음 정리 때나 서버가 다시 시작할 때 사라져요.</li><li>백업: 지우거나 기간이 지나 지운 기록도 서비스 회사의 백업과 복구 기능에 잠시 남아요. 사용 통계, 날짜별 합계, 판매자 화면의 &#39;새 소식&#39;처럼 Cloudflare의 데이터베이스(Durable Object)에 두는 기록은 최대 30일, Supabase의 회원 정보는 최대 7일 동안 남았다가 저절로 지워져요. 판매자는 이 사본을 장애 복구에만 쓰고, 백업에서 되살리면 그 전에 지운 기록을 다시 지워요.</li><li>판매자는 기간 전에도 주문, 문의, 회원, 추천 코드를 판매자 화면에서 지울 수 있어요.</li><li>보관 기간을 정하지 않은 기록을 지울 때는 판매자가 Cloudflare 저장소에서 그 기록을 직접 지워요.</li></ul>\n<h2 id=\"s4\">제3조 제3자 제공</h2>\n<p>판매자는 개인정보를 제3자에게 제공하지 않아요. 법령에 따라 제공해야 하는 경우만 예외예요.</p>\n<p>판매자는 디스코드 서버에 공지를 올리지만, 판매자가 쓴 글만 보내고 이용자의 정보는 보내지 않아요.</p>\n<h2 id=\"s5\">제4조 처리 위탁과 국외 이전</h2>\n<p>판매자는 아래 회사에 개인정보 처리를 맡기고, 그 결과 개인정보가 국외로 이전돼요.</p>\n<h3>Cloudflare</h3>\n<div class=\"tbl\"><table><thead><tr><th>구분</th><th>내용</th></tr></thead><tbody><tr><td>받는 자</td><td>Cloudflare, Inc. (101 Townsend St, San Francisco, CA 94107, USA · dpo@cloudflare.com)</td></tr><tr><td>맡기는 일</td><td>라이선스 서버와 고객센터 운영, 데이터 보관, 요청 전달</td></tr><tr><td>이전되는 항목</td><td>제1조의 정보 전부, 앱이나 브라우저가 서버에 연결할 때의 IP 주소와 요청 정보. 회원 정보는 Supabase로 가는 길에 거쳐 가고, 회원 아이디는 문의, 키 메모, 판매자 작업 기록에도 남아요</td></tr><tr><td>국가</td><td>미국 회사이고, 전 세계에 있는 Cloudflare 데이터센터에서 처리하고 보관해요. 어느 데이터센터인지는 Cloudflare가 정해요</td></tr><tr><td>시기와 방법</td><td>앱이나 브라우저가 판매자 서버에 연결할 때마다, 인터넷으로</td></tr><tr><td>보유 기간</td><td>제2조의 기간</td></tr><tr><td>거부 방법과 효과</td><td>인터넷이 필요한 기능(결제, 키 갱신, 추천 코드, 회원, 고객센터, 사용 통계)을 쓰지 않으면 돼요. 사용 통계는 설정의 &#39;사용 통계 보내기&#39;로 꺼요. 키를 등록한 앱은 켤 때와 켜 둔 동안 키 식별 번호를 확인하니, 이것까지 거부하려면 인터넷 없이 써야 해요. 거부하면 그 기능을 쓸 수 없지만, 등록한 키와 앱의 다른 기능은 인터넷 없이도 써요</td></tr></tbody></table></div>\n<h3>Supabase</h3>\n<div class=\"tbl\"><table><thead><tr><th>구분</th><th>내용</th></tr></thead><tbody><tr><td>받는 자</td><td>Supabase Pte. Ltd. (privacy@supabase.com)</td></tr><tr><td>맡기는 일</td><td>회원 정보 보관</td></tr><tr><td>이전되는 항목</td><td>제1조의 회원 정보, 회원 가입과 로그인의 IP 해시값</td></tr><tr><td>국가 (회원 데이터베이스 위치)</td><td>{{SUPABASE_REGION}}</td></tr><tr><td>시기와 방법</td><td>회원 가입, 로그인 등 회원 기능을 쓸 때 판매자 서버가 인터넷으로 보내요</td></tr><tr><td>보유 기간</td><td>탈퇴하거나 판매자가 회원을 지울 때까지 (IP 해시값은 1시간 남짓, 로그인 세션은 90일). 지운 뒤에도 Supabase의 백업에 최대 7일 남아요</td></tr><tr><td>거부 방법과 효과</td><td>회원 가입을 하지 않으면 돼요. 앱은 회원이 아니어도 쓸 수 있고, 초대 보상과 할인 티켓만 받을 수 없어요</td></tr></tbody></table></div>\n<h3>Lemon Squeezy (카드 결제)</h3>\n<ul><li>카드 결제를 고르면 Lemon Squeezy의 결제창에서 결제해요. 카드 정보, 이름, 메일 주소, 청구지 같은 정보는 Lemon Squeezy가 직접 받아서 Lemon Squeezy의 개인정보 처리방침(https://www.lemonsqueezy.com/privacy)에 따라 처리해요. Lemon Squeezy는 스스로를 판매 대행자(merchant of record)라고 안내하고, 개인정보를 미국에서 처리한다고 안내해요.</li><li>판매자 서버가 Lemon Squeezy로 보내는 것: 결제창을 만들 때 주문 코드(결제를 마친 뒤 돌아올 페이지 주소에도 들어가요), 구독 관리 페이지 주소를 받을 때 구독 번호.</li><li>Lemon Squeezy가 판매자 서버로 보내는 것: 제1조의 &#39;카드 결제&#39; 항목.</li><li>거부하려면 카드 결제 대신 계좌이체 · 직접 결제를 고르면 돼요(판매자가 열어 둔 경우).</li></ul>\n<h3>앱이 직접 연결하는 곳</h3>\n<p>아래는 판매자 서버를 거치지 않고 앱이나 브라우저가 직접 연결해요. 연결하면 상대 회사가 IP 주소와 요청 정보를 받아요.</p>\n<ul><li>GitHub, Inc. (미국): 새 버전 확인과 내려받기. 설정의 &#39;새 버전을 자동으로 확인하고 미리 받아 두기&#39;를 끄면 자동으로 연결하지 않아요.</li><li>macOS에서 Windows 게임 기능을 설정할 때: Wine을 GitHub에서, Steam 설치 파일을 Valve의 배포 서버에서 내려받고, Apple 개발자 페이지를 브라우저로 열어요.</li><li>계좌이체 · 직접 결제: 판매자가 안내한 결제 페이지를 브라우저로 열어요. 그 페이지에 적는 정보는 그 결제 서비스가 처리해요.</li></ul>\n<h2 id=\"s6\">제5조 정보주체의 권리와 행사 방법</h2>\n<ul><li>이용자는 언제든지 자신의 개인정보를 보여 달라고(열람), 고쳐 달라고(정정), 지워 달라고(삭제), 처리를 멈춰 달라고(처리정지) 요구할 수 있고, 동의를 철회할 수 있어요. 법정대리인이나 위임을 받은 사람도 할 수 있어요.</li><li>요구하는 곳: 앱의 &#39;고객센터&#39; → &#39;문의하기&#39;(문의 종류 &#39;기타&#39;), 웹 /help, 또는 제10조의 메일 주소.</li><li>직접 할 수 있는 것:<ul><li>회원 탈퇴: 앱의 &#39;◈ 계정&#39; → &#39;회원 탈퇴&#39;. 운영 중인 데이터베이스의 회원 정보가 바로 지워지고, 백업에는 최대 7일 남아요. 다른 기록에 남는 회원 아이디는 제2조에 적었어요.</li><li>비밀번호 변경: 앱의 &#39;◈ 계정&#39;.</li><li>사용 통계 끄기: 사용권 계약 동의 화면이나 앱의 &#39;설정&#39;에서 &#39;사용 통계 보내기&#39;를 꺼요. 끄면 이 PC의 설치 번호도 지워지고, 서버의 기록은 마지막 연결 뒤 90일이 지나면 지워져요.</li><li>문의 닫기, /help의 &#39;목록에서 빼기&#39;.</li></ul></li><li>본인 확인: 문의는 문의 번호와 확인 코드, 키 정보는 키 전체, 회원 정보는 로그인으로 확인해요. 이것이 없으면 결제 내역 등으로 확인하고, 판매자가 더 물어볼 수 있어요.</li><li>판매자는 요구를 받은 날부터 10일 안에 처리하거나 답해요. 법령에 따라 요구를 들어줄 수 없으면 그 이유를 알려요.</li><li>회원 아이디는 바꿀 수 없어요. 보낸 문의의 글은 고칠 수 없으니 답장으로 바로잡아 주세요.</li></ul>\n<h2 id=\"s7\">제6조 자동 수집 장치</h2>\n<ul><li>쿠키: 판매자 서버는 쿠키를 만들지 않아요.</li><li>웹 /help의 브라우저 저장소(localStorage): 문의를 보내거나 열면 그 브라우저에 문의 번호, 확인 코드, 제목, 저장한 시각을 최대 20개까지 저장해요. 같은 브라우저에서 문의를 다시 열 수 있게 하려는 것이고, 문의를 열 때 말고는 서버로 보내지 않아요. 원하지 않으면 &#39;목록에서 빼기&#39;를 누르거나 브라우저 설정에서 이 사이트의 데이터를 지우거나 막으세요. 저장하지 않아도 /help는 쓸 수 있고, 그때는 문의 번호와 확인 코드를 직접 복사해 두세요.</li><li>앱의 사용 통계: 사용권 계약 동의 화면에서 &#39;사용 통계 보내기&#39;를 켜 둔 경우에만(처음에는 체크되어 있어요), 앱이 켜져 있는 동안 1분에서 1시간 간격(서버가 정해요)으로 제1조의 사용 통계를 보내요. 동의를 마치기 전에는 보내지 않고, 앱의 &#39;설정&#39;에서 끌 수 있어요.</li><li>앱의 결제 확인: 주문을 기다리는 동안(주문한 뒤 90일까지) 앱이 켜져 있으면, 주문 코드를 보내 키가 나왔는지 판매자 서버에 물어봐요. 주문한 뒤 1시간 동안은 1분마다, 하루까지는 15분마다, 그 뒤에는 1시간마다예요(카드 결제는 처음 10분 동안 10초마다). 키를 받거나 주문이 거절 · 환불 · 삭제되면 멈춰요. 기다리기를 멈춘 주문(앱에서 취소했거나 90일이 지난 주문)은 &#39;★ 플랜&#39; 화면을 열 때 40일까지, 한 주문에 1시간에 한 번까지 다시 물어봐요.</li><li>앱의 키 확인: 키를 등록한 앱은 켤 때와 켜 둔 동안 20시간에 한 번까지 키 식별 번호를 보내 판매자가 키를 막았는지 물어봐요. 카드 구독 키는 끝나기 7일 전부터 끝난 뒤 45일까지 6시간마다(PC가 절전에서 깨어나거나 인터넷이 다시 연결될 때도) 구독 번호와 지금 키를 보내 다음 기간의 키를 받아 와요. 구독이 끝났다는 답을 받으면 하루에 한 번까지만 물어봐요.</li><li>앱의 답장 확인: 판매자의 답을 기다리는 문의(마지막으로 바뀐 지 14일 안)가 있으면, 앱이 켜져 있는 동안 30분마다(서버가 바쁘면 최대 2시간마다) 그 문의의 번호와 확인 코드를 보내 답장이 왔는지 물어봐요. 기다리는 문의가 없으면 보내지 않아요.</li><li>이 확인들은 판매자 서버에 새 기록을 남기지 않아요. 답장 확인에는 제2조의 &#39;고객센터 요청의 IP 해시값&#39;이 쓰여요.</li><li>/help, 이 처리방침 페이지(/privacy), 결제 완료 페이지는 외부 스크립트, 글꼴, 분석 도구를 불러오지 않아요.</li></ul>\n<h2 id=\"s8\">제7조 이 PC에만 남는 정보</h2>\n<p>앱은 아래 정보를 이 PC의 SystemBoost 데이터 폴더(%APPDATA%\\SystemBoost, 포터블 판은 앱 옆의 data 폴더)에 두고 서버로 보내지 않아요.</p>\n<ul><li>동의한 사용권 계약의 판과 시각, 언어, 업데이트와 표시 설정, 바꾸기 전 설정의 백업</li><li>프레임 생성 기록(시각, 게임 이름, 모드, 프레임 수)과 엔진 기록(최근 8개)</li><li>macOS에서 등록한 Windows 게임의 이름과 경로</li></ul>\n<p>아래 정보도 이 폴더에 두고, 해당 기능을 쓸 때만 그 일부를 서버로 보내요: 라이선스 키, 기기 번호, 진행 중인 주문(90일 뒤 지워요. 기다리기를 멈춘 주문은 40일), 보낸 문의의 번호, 확인 코드, 제목(최대 20개), 회원 아이디와 로그인 세션, 사용 통계 설정과 설치 번호.</p>\n<p>앱을 지워도 이 폴더는 남아요. 지우려면 앱을 끈 뒤 폴더를 직접 지우세요. 회원이라면 먼저 로그아웃하거나 탈퇴하세요.</p>\n<h2 id=\"s9\">제8조 만 14세 미만 아동</h2>\n<ul><li>회원 가입은 만 14세 이상만 할 수 있어요. 가입할 때 만 14세 이상이라는 확인을 받아요.</li><li>결제, 고객센터, 사용 통계에서는 나이를 묻지 않아요. 만 14세 미만이라면 법정대리인이 대신 문의해 주세요.</li></ul>\n<h2 id=\"s10\">제9조 안전성 확보 조치</h2>\n<p>판매자는 개인정보를 지키려고 다음과 같이 해요.</p>\n<ul><li>앱은 판매자 서버에 암호화된 연결(HTTPS)로 연결하고, 판매자 서버는 Lemon Squeezy에 HTTPS로 연결해요.</li><li>비밀번호는 서버만 아는 값과 섞은 뒤 bcrypt로 해시해서 저장하고, 원래 비밀번호는 저장하지 않아요. 복구 코드, 로그인 세션, 문의 확인 코드도 서버에는 해시값만 저장해요.</li><li>IP 해시값은 서버만 아는 값을 섞어 만들어요. 고객센터의 IP 해시값은 마지막 요청 뒤 1시간까지만 둬요. 판매자 서버는 IP 주소를 그대로 저장하지 않아요. 판매자 화면의 비밀번호를 틀린 접속도 IP 해시값으로 세요(마지막으로 틀린 뒤 15분).</li><li>카드 번호는 받지 않아요. 고객센터로 온 키 전체는 확인에만 쓰고 저장하지 않아요. 문의 확인 코드는 주소(URL)에 넣지 않아요.</li><li>판매자 화면의 정보는 판매자 비밀번호가 있어야 볼 수 있고, 비밀번호를 여러 번 틀리면 잠겨요(같은 IP에서 5번 틀리면 마지막으로 틀린 뒤 15분, 모두 합쳐 한 시간(정시 기준)에 20번 틀리면 그 시간이 끝날 때까지).</li><li>회원 데이터베이스는 판매자 서버만 비밀 키로 접근할 수 있게 권한을 막아 두었어요.</li><li>카드 결제 알림은 Lemon Squeezy의 서명이 맞는 것만 받아요.</li><li>고객센터와 회원 기능은 요청 횟수를 제한해요(같은 IP의 1시간 한도, 고객센터는 하루 한도도 있어요).</li></ul>\n<h2 id=\"s11\">제10조 개인정보 보호책임자</h2>\n<p>개인정보에 관한 문의, 불만, 피해 구제는 아래로 연락해 주세요. 앱의 &#39;고객센터&#39;로 보내도 돼요.</p>\n<ul><li>개인정보 보호책임자: {{OWNER_NAME}}</li><li>메일: {{OWNER_EMAIL}}</li></ul>\n<h2 id=\"s12\">제11조 권익침해 구제 방법</h2>\n<p>개인정보 침해로 상담이나 구제가 필요하면 아래 기관에 문의할 수 있어요.</p>\n<ul><li>개인정보 분쟁조정위원회: (국번없이) 1833-6972, www.kopico.go.kr</li><li>개인정보침해 신고센터(한국인터넷진흥원): (국번없이) 118, privacy.kisa.or.kr</li><li>공소청: (국번없이) 1301, www.spo.go.kr</li><li>경찰청 사이버범죄 신고시스템: (국번없이) 182, ecrm.police.go.kr</li></ul>\n<h2 id=\"s13\">제12조 처리방침의 변경</h2>\n<ul><li>이 방침을 바꾸면 시행일 7일 전부터 이 페이지와 앱에 알려요. 처리하는 항목, 국외 이전, 보유 기간처럼 이용자에게 중요한 내용이 바뀌면 30일 전부터 알려요.</li><li>시행일: {{EFFECTIVE_DATE}}</li></ul>\n</main>\n</body>\n</html>\n",
 "en": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>SystemBoost privacy policy (summary)</title>\n<style nonce=\"__NONCE__\">\n:root{--bg:#0b0b0c;--card:#141416;--line:#2a2a2e;--text:#e8e6e3;--muted:#8b8a88;--accent:#ff7a1a;--warn:#f5c04a}\n*{box-sizing:border-box}\nbody{background:var(--bg);color:var(--text);font-family:system-ui,-apple-system,\"Segoe UI\",\"Malgun Gothic\",sans-serif;max-width:900px;margin:0 auto;padding:24px 16px 64px;line-height:1.65;overflow-wrap:anywhere}\nheader{display:flex;align-items:baseline;justify-content:space-between;gap:12px;flex-wrap:wrap;font-size:14px}\nheader .brand{color:var(--accent);font-weight:700}header nav{display:flex;gap:16px;flex-wrap:wrap}\na{color:var(--accent)}\nh1{color:var(--accent);font-size:26px;margin:20px 0 12px}h2{font-size:19px;margin:32px 0 10px;padding-top:12px;border-top:1px solid var(--line)}h3{font-size:16px;margin:20px 0 8px}\np,li{margin:6px 0}ul{padding-left:22px}\n.toc{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:12px 16px;margin:18px 0;font-size:14px}.toc ol{margin:6px 0 0;padding-left:22px}\n.tbl{overflow-x:auto;margin:10px 0}\ntable{border-collapse:collapse;width:100%;font-size:14px}\nth,td{border:1px solid var(--line);padding:8px 10px;text-align:left;vertical-align:top}\nth{background:var(--card);color:var(--muted);font-weight:600}td{min-width:7em}\n.blank{color:var(--warn);font-weight:600}\n</style>\n</head>\n<body>\n<header><span class=\"brand\">SystemBoost</span><nav><a href=\"/help?lang=en\">Support</a><a href=\"/privacy\" hreflang=\"ko\">한국어 (the policy)</a></nav></header>\n<main>\n<h1>SystemBoost privacy policy (summary)</h1>\n<p>This page is a summary in English. The Korean text is the policy; if the two differ, the Korean text governs.</p>\n<p>Effective date: {{EFFECTIVE_DATE}}</p>\n<nav class=\"toc\" aria-label=\"Contents\"><b>Contents</b><ol><li><a href=\"#s1\">At a glance</a></li><li><a href=\"#s2\">What is processed</a></li><li><a href=\"#s3\">How long</a></li><li><a href=\"#s4\">Sharing, processors and transfers abroad</a></li><li><a href=\"#s5\">Your rights</a></li><li><a href=\"#s6\">Contact</a></li></ol></nav>\n<h2 id=\"s1\">At a glance</h2>\n<ul><li>The app works without an account. Sign-up asks for no email address or name.</li><li>Card numbers are entered only in the Lemon Squeezy checkout. They never reach the SystemBoost app or the seller&#39;s server, and the server stores nothing about cards.</li><li>The seller&#39;s server runs on Cloudflare (a US company) and member accounts are kept in Supabase, so personal information is processed and stored outside Korea.</li><li>Some records have no set retention period (key records and the email index among them). The Korean policy, Article 2, lists every record and how long it stays.</li><li>Personal information is not used for advertising or marketing, and is not sold or given to anyone.</li></ul>\n<h2 id=\"s2\">What is processed</h2>\n<ul><li>Starting an app with a registered key, and at most once every 20 hours while it runs: the key ID (16 characters computed from the key), to check whether the key was blocked. Not stored.</li><li>Renewing a subscription key: the subscription number and the key in use (only checked against that subscription). Not stored.</li><li>Bank transfer and direct payment: the order code, plan, status and times, the payer name and payment memo you type, a discount ticket&#39;s percentage; when approved, the key ID and an email address the seller may enter; a rejection reason or refund time.</li><li>Card payment: from Lemon Squeezy, the payment email, subscription number, order number, payment (invoice) number, plan, next payment date and whether it is a test payment. Other details in Lemon Squeezy&#39;s notice (such as the name) are not stored.</li><li>Every key: the full key text and its record (plan, dates, how it was received, email address, note, subscription number, blocked or not). The note can hold the order code, the payer name and memo of a direct payment, a referral code, or a member ID. The key itself contains the email address, so showing the key to someone shows the email address too.</li><li>Referral and invite codes: the code and a random device number made by the app.</li><li>Members (optional): ID, password and recovery code as hashes only, sign-up and last login times, the consent text version and time, invite codes and relations, rewards, discount tickets (including the order code they were used on), failed logins and lockout, blocked or not, login sessions as hashes.</li><li>Support requests and refund requests: category, subject, messages and replies, times, status, consent time, language, the access code as a hash, the member ID when sent from a signed-in app, and what you choose to give (contact, order code, key ID, app details). A refund request also carries the order and key details the server holds. A full key sent for a check is never stored.</li><li>Usage statistics (optional: chosen with &#39;Send usage statistics&#39; on the agreement screen, ticked at first, changeable later in Settings; nothing is sent before the agreement is accepted): a random install number, app version, operating system, plan, frame generation multiplier, one-click boost use, the country (from Cloudflare), first and last connection. No IP address is stored with them.</li><li>Abuse limits: hashes made from IP addresses with a value only the server knows (sign-up, login, support, wrong dashboard passwords), and a daily count per key ID of subscription-management links handed out.</li><li>The seller&#39;s activity log: what the seller did and automatic steps, with details such as order codes, key IDs, subscription numbers, member IDs, email addresses (masked) and key notes, payer names and memos (first character only).</li><li>The dashboard access log: each dashboard sign-in and each view of member or purchase data, with the time, a one-way hash of the address and the screen and item viewed (never search words).</li><li>Deleted member IDs: a salted hash of an ID that was deleted, so nobody else can register the same ID.</li><li>If the seller turns on Cloudflare&#39;s logs: request addresses and server error records, for the period Cloudflare sets.</li><li>Background checks by the running app: while an order waits (up to 90 days after ordering), its order code every minute for the first hour, every 15 minutes for the first day, then hourly (a card checkout every 10 seconds for its first 10 minutes), until the key arrives or the order is rejected, refunded or deleted; an order the app stopped waiting for (cancelled in the app, or older than 90 days) is asked about again when the &#39;★ Plans&#39; page opens, for up to 40 days and at most hourly; a subscription key, from 7 days before its end until 45 days after it, every 6 hours (and after the PC wakes or the network returns), with its subscription number and the key in use, to fetch the next period&#39;s key (once a day after the server answered that the subscription ended); while a support request waits for the seller&#39;s answer (changed in the last 14 days), its number and access code every 30 minutes (up to every 2 hours when the server is busy). None of these checks leaves a new record on the server.</li></ul>\n<h2 id=\"s3\">How long</h2>\n<ul><li>Orders: 90 days from the last change. Key-collection records: 7 days (card) or 30 days (direct payment).</li><li>Key records, the email index, links between Lemon Squeezy orders and keys, blocked keys, subscription plans and referral codes: no set retention period, kept until the seller deletes them.</li><li>Members: until they leave or the seller deletes the account; leaving deletes the account from the live database at once, and Supabase backups keep it up to 7 more days. The member ID stays in invite-reward key notes (no set period), the activity log (180 days) and support requests (their own period).</li><li>Login sessions: 90 days. Sign-up and login IP hashes: a little over an hour. Support IP hashes: up to 1 hour after the last request.</li><li>Support requests: 3 years for payment and refund requests, 1 year for the rest, from the last change.</li><li>Usage statistics: 90 days after the last connection. Activity log: 180 days. Dashboard access log: one year. Wrong dashboard password counts (by address hash): 15 minutes after the last miss. Daily portal-link counts: 2 days.</li><li>Hashes of deleted member IDs: no set retention period, kept until the seller deletes them.</li><li>A subscription&#39;s list of key IDs: 400 days after a key was last added. Marks that a card payment notice was already handled (subscription and payment numbers): 400 days.</li><li>Backups: deleted records stay for a while in the providers&#39; recovery copies, up to 30 days for Cloudflare&#39;s database (usage statistics, daily totals, the dashboard&#39;s news) and up to 7 days for member accounts in Supabase. They are used only to recover from a failure, and anything deleted before a restore is deleted again.</li><li>Requests saved by /help in your browser: until you remove them.</li></ul>\n<h2 id=\"s4\">Sharing, processors and transfers abroad</h2>\n<ul><li>Personal information is not given to third parties except where the law requires it. Discord announcements carry only what the seller writes.</li><li>Cloudflare, Inc. (USA, dpo@cloudflare.com) runs the server and stores its data in data centers worldwide.</li><li>Supabase Pte. Ltd. (privacy@supabase.com) stores member accounts. Database location: {{SUPABASE_REGION}}</li><li>Lemon Squeezy handles card payments under its own privacy policy and receives the order code and, for the subscription page, the subscription number.</li><li>The app itself connects to GitHub for updates (this can be turned off in Settings) and, for the macOS Windows-games feature, to GitHub, Valve and Apple.</li></ul>\n<h2 id=\"s5\">Your rights</h2>\n<ul><li>You can ask to see, correct or delete your information, to stop its processing, or withdraw consent: through Support in the app, /help, or the email address below. The seller answers within 10 days.</li><li>You can delete your account under &#39;◈ Account&#39; → &#39;Delete account&#39;, turn off &#39;Send usage statistics&#39; on the agreement screen or in Settings, close your requests, and remove saved requests on /help (&#39;Remove from list&#39;).</li><li>Sign-up is for people aged 14 or over.</li></ul>\n<h2 id=\"s6\">Contact</h2>\n<ul><li>Privacy officer: {{OWNER_NAME}}</li><li>Email: {{OWNER_EMAIL}}</li><li>Korean authorities for privacy complaints: Personal Information Dispute Mediation Committee 1833-6972, KISA Privacy Infringement Report Center 118, Korean National Police Agency Cyber Bureau 182.</li></ul>\n</main>\n</body>\n</html>\n"
};
